import re

def parse_duration(s):
    """Parse duration string like '1h30m', '45s', '2h' into seconds."""
    pattern = re.compile(r'(\d+)([hms])')
    matches = pattern.findall(s)
    if not matches:
        raise ValueError(f"Invalid duration format: {s}")

    total = 0
    for num_str, unit in matches:
        num = int(num_str)
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
    return total
